fn format_date(seconds: u64) -> String {
    // Clamp to 9999-12-31 so the year always has four digits (len == 10).
    const MAX_SECS: u64 = 253_402_300_799;
    let secs = if seconds > MAX_SECS { MAX_SECS } else { seconds };
    let days = (secs / 86_400) as i64;

    // Civil-from-days (Howard Hinnant's algorithm).
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = crate::wasi::clocks::wall_clock::now();
        RunInfo {
            date: format_date(now.seconds),
            started: now.seconds,
        }
    }
}

